class StatBar : public QWidget {
    Q_OBJECT
public:
    StatBar(QWidget* parent = nullptr);
    void setValue(int value);
    void animateTo(int value);
protected:
    void paintEvent(QPaintEvent* event) override;
private:
    int currentValue;
    QPropertyAnimation* animation;
};

class GameWindow : public QWidget {
    Q_OBJECT

public:
    GameWindow(Wolf& w, DecisionTree& t, PriorityQueue& e, GameStack& h, ActionQueue& a, Inventory& i, Pack& p, QWidget* parent = nullptr);

private slots:
    void onChoiceA();
    void onChoiceB();
    void onUndo();
    void onSave();
    void onLoad();
    void onInventory();
    void onPack();
    void updateStats();

private:
    Wolf& wolf;
    DecisionTree& tree;
    PriorityQueue& events;
    GameStack& history;
    ActionQueue& actions;
    Inventory& inventory;
    Pack& pack;

    QLabel* storyLabel;
    QLabel* statsLabel;
    QPushButton* buttonA;
    QPushButton* buttonB;
    QPushButton* undoButton;
    QPushButton* saveButton;
    QPushButton* loadButton;
    QPushButton* inventoryButton;
    QPushButton* packButton;
    StatBar* healthBar;
    StatBar* hungerBar;
    StatBar* energyBar;
    StatBar* spiritBar;
    QLabel* wolfGraphic;

    std::random_device rd;
    std::mt19937 gen{rd()};
    std::uniform_real_distribution<> dis{0.0, 1.0};

    void updateDisplay();
    void processChoice(bool isA);
    void checkEvents();
};

#endif

